    def rules(self):
        return [v for k,v in self.__class__.__dict__.items() if k.startswith("RULE_")]
    def evaluate(self, text):
        value = str(text or "").strip()
        return {"rulebook": self.ID, "rule_count": len(self.rules()), "context_present": bool(value)}
    def recommendation(self, text):
        result = self.evaluate(text)
        return "Proceed with monitored automation" if result["context_present"] else "Request additional customer context"
